                pin = t[1]; macros[cur]['pins'][pin] = {'dir': None, 'use': None, 'layers': {}}
            elif pin is not None and t[0] == 'DIRECTION':
                macros[cur]['pins'][pin]['dir'] = t[1]
            elif pin is not None and t[0] == 'USE':
                macros[cur]['pins'][pin]['use'] = t[1]
            elif t[0] == 'LAYER':
                layer = t[1]
                if pin is not None:
                    macros[cur]['pins'][pin]['layers'][layer] = macros[cur]['pins'][pin]['layers'].get(layer, 0)
            elif t[0] == 'RECT' and pin is not None and layer is not None:
                macros[cur]['pins'][pin]['layers'][layer] += 1
            elif t[0] == 'OBS':
                pin = None
            elif t[0] == 'END' and len(t) > 1 and t[1] == cur:
