sig_e = sum(1 for m in e.values() for pin in m['pins'].values() if pin['use'] == 'SIGNAL')
print('signal pins plain/ecos:', sig_p, sig_e)

m2 = via1 = 0
bad = []
for m in e.values():
    for name, pin in m['pins'].items():
        if pin['use'] != 'SIGNAL':
            continue
        c2 = pin['layers'].get('MET2', 0); cv = pin['layers'].get('VIA1', 0)
        m2 += c2; via1 += cv
        if c2 != 1 or cv != 1:
            bad.append((m, name, c2, cv))
print('ecos MET2 rects:', m2, 'VIA1 rects:', via1, 'pins not 1+1:', len(bad))

diff_pow = 0
for m in p:
    for pn in ('VDD', 'VSS'):
        a = p[m]['pins'].get(pn, {}).get('layers')
        b = e[m]['pins'].get(pn, {}).get('layers')
        if a != b:
            diff_pow += 1
print('power-pin rect mismatches:', diff_pow)

diff_m1 = 0
for m in p:
