            dd.append((m, n, p[m]['pins'][n]['dir'], e[m]['pins'][n]['dir']))
print('direction diffs plain-vs-ecos:', len(dd), dd[:5])

missing = [(m, n) for m in p for n in p[m]['pins'] if n not in e[m]['pins']]
